# area: self_classmethods
# hypothesis: Self in an inherited classmethod, property and method parameter binds to the receiving class through a diamond, so passing a sibling or base instance is rejected.
from typing import Self, reveal_type


class Base:
    @classmethod
    def make(cls) -> Self:
        return cls()

    @property
    def me(self) -> Self:
        return self

    def pair(self, other: tuple[Self, int]) -> Self:
        return other[0]


class Left(Base):
    pass


class Right(Base):
    pass


class Bottom(Left, Right):
    pass


reveal_type(Bottom.make())  # Bottom
reveal_type(Bottom().me)  # Bottom
reveal_type(Left.make())  # Left
b = Bottom()
print(type(Bottom.make()).__name__, type(b.me).__name__)
print(type(b.pair((Bottom(), 1))).__name__)
b.pair((Left(), 1))  # expect-error: Left is not Bottom
Left.make().pair((Right(), 2))  # expect-error: Right is not Left
